sys_script_include.script:
var GetConnectionDetails = Class.create();
GetConnectionDetails.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getConnectionDetails: function() {
		var response = {};
		response["mid_server"] = gs.getProperty("x_1784056_sixscape.Mid Server Name") || '';
		response["end_point"] = gs.getProperty("x_1784056_sixscape.End Point") || '';
		response["application_id"] = gs.getProperty("x_1784056_sixscape.Application ID") || '';
		response["application_secret"] = gs.getProperty("x_1784056_sixscape.Application Secret") || '';
		response["key_manager_pin"] = gs.getProperty("x_1784056_sixscape.Key Manager Pin") || '';
		return JSON.stringify(response);
	},

    type: 'GetConnectionDetails'
});
